export type PlannedOutcome = {
  status: Exclude<RunStatus, "running" | "skipped_overlap">;
  exit_code: number | null;
  duration_secs: number;
  /** Run-history prose (the run view's detail). */
  detail: string;
  /** Ledger detail after "<job_id> "; {dur} = the duration label. */
  ledger: string;
  stdout_tail?: string | null;
  stderr_tail?: string | null;
  error?: string | null;
  matched_pattern?: string | null;
  /** bridge-wake only: wake pings this run mints into the outbox. */
  mint_pings?: number;
};

const ok = (
  duration_secs: number,
  detail: string,
  extra: Partial<PlannedOutcome> = {},
): PlannedOutcome => ({
  status: "ok",
  exit_code: 0,
  duration_secs,
  detail,
  ledger: "completed · {dur}",
  ...extra,
});

