// ---------------------------------------------------------------
export function hash01(text: string): number {
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return ((h >>> 0) % 1000) / 1000;
}

export function intervalSecs(every: string): number {
  const m = /^(\d+)([smh])$/.exec(every);
  if (!m) return 900;
  const n = Number(m[1]);
  return m[2] === "s" ? n : m[2] === "m" ? n * 60 : n * 3600;
}

export function cadenceStepMs(cadence: Cadence): number {
  switch (cadence.type) {
    case "interval":
      return intervalSecs(cadence.every) * 1000;
    case "daily":
      return 86_400_000;
    case "weekly":
      return 604_800_000;
  }
}

export function fmtClock(at: string): string {
  const [h, m] = at.split(":").map(Number);
  const hh = h ?? 0;
  const suffix = hh >= 12 ? "PM" : "AM";
  const h12 = hh % 12 === 0 ? 12 : hh % 12;
  return `${h12}:${String(m ?? 0).padStart(2, "0")} ${suffix}`;
}

const DOW_NAMES: Record<string, string> = {
  mon: "Mondays",
  monday: "Mondays",
  tue: "Tuesdays",
  tues: "Tuesdays",
  tuesday: "Tuesdays",
  wed: "Wednesdays",
  wednesday: "Wednesdays",
  thu: "Thursdays",
  thur: "Thursdays",
  thurs: "Thursdays",
  thursday: "Thursdays",
  fri: "Fridays",
  friday: "Fridays",
  sat: "Saturdays",
  saturday: "Saturdays",
  sun: "Sundays",
  sunday: "Sundays",
};

/** The adapter's cadence_label — server-computed (contract 09). */
export function cadenceLabel(cadence: Cadence): string {
  if (cadence.type === "daily") return `daily ${fmtClock(cadence.at)}`;
  if (cadence.type === "weekly") {
    const days = cadence.dow
      .map((d) => DOW_NAMES[d.toLowerCase()] ?? d)
      .join(", ");
    return `${days} ${fmtClock(cadence.at)}`;
  }
  const secs = intervalSecs(cadence.every);
  if (secs < 60) return secs === 1 ? "every second" : `every ${secs} seconds`;
  if (secs < 3600) {
    const mins = secs / 60;
    return mins === 1 ? "every minute" : `every ${mins} minutes`;
  }
  const hours = secs / 3600;
  if (hours === 1) return "hourly";
  if (hours === 24) return "daily";
  if (hours === 168) return "weekly";
  return `every ${hours} hours`;
}

export function expectedWakesPerDay(cadence: Cadence): number {
  if (cadence.type === "daily") return 1;
  if (cadence.type === "weekly")
    return Math.round((cadence.dow.length / 7) * 100) / 100;
  return Math.round((86400 / intervalSecs(cadence.every)) * 100) / 100;
}

export function fmtDuration(secs: number): string {
  if (secs < 60) return `${secs.toFixed(1)} s`;
  const m = Math.floor(secs / 60);
  const s = Math.round(secs % 60);
  if (m < 60) return `${m}m ${s}s`;
  return `${Math.floor(m / 60)}h ${m % 60}m`;
}

/** Contract 06's outcome_label(), the pipeline's one label map. */
export function outcomeLabel(
  status: RunStatus,
  exitCode: number | null,
): string {
  switch (status) {
    case "running":
      return "Running";
    case "skipped_overlap":
      return "Skipped";
    case "ok":
      return exitCode === 0 || exitCode === null
        ? "OK"
        : `Exit ${exitCode} · normal`;
    case "failed":
      return `Failed · exit ${exitCode}`;
    case "timeout":
      return "Timed out";
    case "could_not_start":
      return "Could not start";
  }
}

// ---------------------------------------------------------------
// Timezone-aware next-due for daily/weekly cadences.

function zonedParts(tz: string, ms: number) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: tz,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
    weekday: "short",
  }).formatToParts(new Date(ms));
  const get = (t: string) => parts.find((p) => p.type === t)?.value ?? "";
  return {
    year: Number(get("year")),
    month: Number(get("month")),
    day: Number(get("day")),
    hour: Number(get("hour")),
    minute: Number(get("minute")),
    weekday: get("weekday"),
  };
}

function utcForZoned(
  tz: string,
  year: number,
  month: number,
  day: number,
  hour: number,
  minute: number,
): number {
  let guess = Date.UTC(year, month - 1, day, hour, minute);
  for (let i = 0; i < 3; i++) {
    const p = zonedParts(tz, guess);
    const seen = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute);
    const want = Date.UTC(year, month - 1, day, hour, minute);
    if (seen === want) return guess;
    guess += want - seen;
  }
  return guess;
}

const DOW_INDEX: Record<string, number> = {
  Sun: 0,
  Mon: 1,
  Tue: 2,
  Wed: 3,
  Thu: 4,
  Fri: 5,
  Sat: 6,
};

function dowIndexOf(name: string): number {
  const key = name.slice(0, 3).toLowerCase();
  const full: Record<string, number> = {
    sun: 0,
    mon: 1,
    tue: 2,
    wed: 3,
    thu: 4,
    fri: 5,
    sat: 6,
  };
  return full[key] ?? 1;
}

export function nextDueFor(entry: JobEntry, now: number): number | null {
  if (entry.status !== "active") return null;
  const cadence = entry.cadence;
  const tz = entry.timezone ?? DEFAULT_TZ;
  if (cadence.type === "interval") {
    const step = intervalSecs(cadence.every) * 1000;
    return now + Math.round(step * (0.15 + 0.8 * hash01(entry.id)));
  }
  const [hh, mm] = cadence.at.split(":").map(Number);
  const p = zonedParts(tz, now);
  if (cadence.type === "daily") {
    let candidate = utcForZoned(tz, p.year, p.month, p.day, hh ?? 0, mm ?? 0);
    if (candidate <= now) {
      const next = new Date(Date.UTC(p.year, p.month - 1, p.day + 1));
      candidate = utcForZoned(
        tz,
        next.getUTCFullYear(),
        next.getUTCMonth() + 1,
        next.getUTCDate(),
        hh ?? 0,
        mm ?? 0,
      );
    }
    return candidate;
  }
  // weekly
  const wanted = new Set(cadence.dow.map(dowIndexOf));
  for (let add = 0; add < 8; add++) {
    const dayDate = new Date(Date.UTC(p.year, p.month - 1, p.day + add));
    const dow = dayDate.getUTCDay();
    // The zoned weekday of that calendar day matches the UTC
    // weekday for the candidate construction used here.
    void DOW_INDEX;
    if (!wanted.has(dow)) continue;
    const candidate = utcForZoned(
      tz,
      dayDate.getUTCFullYear(),
      dayDate.getUTCMonth() + 1,
      dayDate.getUTCDate(),
      hh ?? 0,
      mm ?? 0,
    );
    if (candidate > now) return candidate;
  }
  return now + 604_800_000;
}

// ---------------------------------------------------------------
// The store.

export type JobRuntime = {
  entry: JobEntry;
  history: RunView[];
  dues: { due: string; outcome: "fired" | "collapsed" | "skipped_overlap"; collapsed: number }[];
  nextDue: number | null;
  running: { plan: PlannedOutcome; completesAt: number; run: RunView } | null;
  planIdx: number;
  stats: { runs24h: number; failures24h: number };
  /** The entry's live config state (knob-bearing entries
   *  only): the version stamp the CAS guard checks and the
   *  current values the engine reads at fire time. */
  config: { version: number; values: Record<string, number> } | null;
};

export type Store = {
  jobs: Map<string, JobRuntime>;
  pings: PingRecord[];
  ledger: LedgerEventRaw[];
  flapActive: boolean;
  bootAt: number;
  lastTick: number;
  pid: number;
  pingSeq: number;
  wakeupsServed24h: number;
  pingsCreated24h: number;
};

const iso = (ms: number) => new Date(ms).toISOString();

function makeRun(
  at: number,
  due: number,
  plan: PlannedOutcome,
  collapsed = 0,
): RunView {
  return {
    ts: iso(at),
    due: iso(due),
    status: plan.status,
    exit_code: plan.exit_code,
    label: outcomeLabel(plan.status, plan.exit_code),
    matched_pattern: plan.matched_pattern ?? null,
    collapsed,
    error: plan.error ?? null,
    stdout_tail: plan.stdout_tail ?? null,
    stderr_tail: plan.stderr_tail ?? null,
    duration_label: fmtDuration(plan.duration_secs),
    detail: plan.detail,
  };
}

function skipRow(at: number, due: number): RunView {
  return {
    ts: iso(at),
    due: iso(due),
    status: "skipped_overlap",
    exit_code: null,
    label: "Skipped",
    matched_pattern: null,
    collapsed: 0,
    error: null,
    stdout_tail: null,
    stderr_tail: null,
    duration_label: null,
    detail: "Skipped · previous run still active",
  };
}

function seedJobHistory(entry: JobEntry, now: number): JobRuntime {
  const plans = planFor(entry.id);
  const step = cadenceStepMs(entry.cadence);
  const frac = hash01(entry.id);
  const startIdx = Math.floor(frac * plans.length) % plans.length;
  const history: RunView[] = [];
  const dues: JobRuntime["dues"] = [];

  if (entry.kind === "agent") {
    return {
      entry,
      history,
      dues,
      nextDue: nextDueFor(entry, now),
      running: null,
      planIdx: 0,
      stats: { runs24h: 24, failures24h: 0 },
      config: null,
    };
  }

  // bridge-wake's storyboard specimen: two runs then a skip.
  if (entry.id === "bridge-wake") {
    const rows: [number, PlannedOutcome | "skip"][] = [
      [20, plans[0]!],
      [35, plans[1]!],
      [50, "skip"],
      [65, plans[3]!],
      [80, plans[2]!],
    ];
    for (const [mins, plan] of rows) {
      const at = now - mins * 60_000;
      const run = plan === "skip" ? skipRow(at, at - 1000) : makeRun(at, at - 1500, plan);
      history.push(run);
      dues.push({
        due: run.due,
        outcome: plan === "skip" ? "skipped_overlap" : "fired",
        collapsed: 0,
      });
    }
    return {
      entry,
      history,
      dues,
      nextDue: nextDueFor(entry, now),
      running: null,
      planIdx: 1,
      stats: { runs24h: 1412, failures24h: 0 },
      config: null,
    };
  }

  const rowCount = 6;
  let at = now - Math.round(step * (0.25 + 0.6 * frac));
  for (let i = 0; i < rowCount; i++) {
    const plan = plans[(startIdx + i) % plans.length]!;
    const collapsed =
      entry.id === "wb-progress-programme-b-t-01k8r0000000000000000000b2" && i === 1
        ? 3
        : 0;
    const run = makeRun(at, at - 1500, plan, collapsed);
    if (collapsed > 0) run.detail = "Completed · caught up 3 collapsed points";
    history.push(run);
    dues.push({
      due: run.due,
      outcome: collapsed > 0 ? "collapsed" : "fired",
      collapsed,
    });
    at -= step;
  }

  const perDay = expectedWakesPerDay(entry.cadence);
  const runs24h =
    entry.cadence.type === "interval"
      ? Math.min(1440, Math.round(perDay * (0.92 + 0.08 * frac)))
      : entry.cadence.type === "daily"
        ? 1
        : frac < 0.5
          ? 1
          : 0;
  const failedRows = history.filter((r) => r.status === "failed").length;
  const failures24h =
    entry.cadence.type === "interval" && rowCount > 0
      ? Math.round(failedRows * (runs24h / rowCount))
      : failedRows;

  return {
    entry,
    history,
    dues,
    nextDue: nextDueFor(entry, now),
    running: null,
    planIdx: (startIdx + rowCount) % plans.length,
    stats: { runs24h, failures24h },
    config: null,
  };
}

