export function buildStore(now: number): Store {
  const jobs = new Map<string, JobRuntime>();
  for (const entry of ENTRIES) {
    const rt = seedJobHistory(entry, now);
    const configSeed = ENTRY_CONFIG[entry.id];
    if (configSeed) {
      rt.config = {
        version: 1,
        values: Object.fromEntries(
          configSeed.knobs.map((knob) => [knob.key, knob.value]),
        ),
      };
    }
    jobs.set(entry.id, rt);
  }
  return {
    jobs,
    pings: seedPings(now),
    ledger: seedLedger(now),
    flapActive: true,
    bootAt: now - 26 * 3600_000 - 14 * 60_000,
    lastTick: now - 20_000,
    pid: 4213,
    pingSeq: 100,
    wakeupsServed24h: 311,
    pingsCreated24h: 96,
  };
}
